/**
 * Shared detectors for the design-system conformance ratchet (FAR-2710, FAR-2774).
 *
 * This module is the SINGLE scanning implementation. The guard spec
 * (`frontend/src/__tests__/design-system-guard.spec.ts`) and the baseline writer
 * it owns (`DS_GUARD_WRITE_BASELINE=1`) both call `countPatterns()` from here, so
 * the checked-in baseline can never be generated by a detector that differs from
 * the one enforcing it. Add a pattern here, add it to `PATTERNS`, and the guard,
 * the writer and the unit tests all pick it up.
 *
 * Detection is deliberately textual and objective - never semantic. Each
 * pattern is a one-line drift fingerprint that a reviewer can explain; a
 * legitimate design call that happens to match stays in the baseline rather than
 * being re-litigated.
 *
 * Markup patterns (`card_container`, `card_header`, `raw_button`, `raw_input`)
 * scan the TEMPLATE only. `<script>` and `<style>` blocks and HTML comments are
 * stripped first, so a tag named inside a script string, a CSS rule or a
 * commented-out block is not counted. The element names matched by `raw_button`
 * and `raw_input` are case-sensitive, so the capitalised PrimeVue components
 * (`<Button>`, `<InputText>`) are not counted as raw elements.
 *
 * Import patterns (`raw_dialog`, `primevue_badge`) scan the script block: any
 * `import ... from '<module>'` form (default, named, namespace, aliased or
 * side-effect) matches, and a commented-out import does not.
 */

export const PATTERNS = [
  'card_container',
  'card_header',
  'raw_dialog',
  'raw_button',
  'raw_input',
  'primevue_badge',
] as const

export type Pattern = (typeof PATTERNS)[number]

/** Per-pattern, per-file counts keyed by repo-relative path. */
export type Counts = Record<Pattern, Record<string, number>>

const HTML_COMMENT = /<!--[\s\S]*?-->/g
const SCRIPT_BLOCK = /<script\b[\s\S]*?<\/script>/gi
const STYLE_BLOCK = /<style\b[\s\S]*?<\/style>/gi
const JS_BLOCK_COMMENT = /\/\*[\s\S]*?\*\//g

const CLASS_ATTR = /(?<![-\w])(?::class|class)\s*=\s*(?:"([^"]*)"|'([^']*)')/gs
const CLASS_TOKEN_SEPARATORS = /[\s,]+/
const CLASS_TOKEN_NOISE = /[\[\]'"`{}()]/g
const PADDING_TOKEN = /^p-(?:\d+(?:\.\d+)?|px|\[[^\]]+\])$/
const TITLE_ATTR = /(?<![-\w])title\s*=/
const PADDING_NONE = /(?<![-\w])padding\s*=\s*(?:"none"|'none'|"'none'"|'"none'")/

/** A raw HTML `<button>` opening tag (case-sensitive: `<Button>` is a component). */
const RAW_BUTTON_TAG = /<button(?=[\s>/])/g
/** A raw HTML `<input>` opening tag (case-sensitive: `<InputText>` is a component). */
const RAW_INPUT_TAG = /<input(?=[\s>/])/g
/**
 * An `import` statement whose module specifier is `module`.
 *
 * Anchored to a line start and allowed to span newlines, so a multi-line
 * default/named/namespace import matches. The `from` form is required when the
 * statement has bindings, which keeps the specifier anchored to the module the
 * statement actually imports (a later string on the line is not a match). The
 * negative lookahead stops the body from consuming the start of the NEXT
 * `import` statement, so two adjacent imports are counted separately. The bare
 * side-effect form (`import 'module'`) is the first alternative.
 */
function importStatement(module: string): RegExp {
  const quoted = `["']${module}["']`
  return new RegExp(
    `^[ \\t]*import(?:[ \\t]+${quoted}|\\s+(?:(?!^[ \\t]*import\\b)[\\s\\S])*?\\bfrom\\s+${quoted})`,
    'gm',
  )
}

const RAW_DIALOG_IMPORT = importStatement('primevue/dialog')
const PRIMEVUE_BADGE_IMPORT = importStatement('primevue/badge')

/** Replace a matched region with spaces, or drop it, preserving line numbers. */
function stripRegions(text: string, pattern: RegExp, preserveLines: boolean): string {
  if (!preserveLines) return text.replace(pattern, '')
  return text.replace(pattern, (match) => match.replace(/[^\n]/g, ' '))
}

export function stripHtmlComments(text: string, preserveLines = false): string {
  return stripRegions(text, HTML_COMMENT, preserveLines)
}

/** Remove JavaScript block comments (`/* ... *\/`), leaving line comments to the anchors. */
export function stripJsBlockComments(text: string): string {
  return text.replace(JS_BLOCK_COMMENT, '')
}

export interface StripNonTemplateOptions {
  /**
   * Replace each stripped region with spaces while keeping newlines, so line
   * numbers computed from the result stay true. Defaults to false (drop the
   * region).
   */
  preserveLines?: boolean
}

/**
 * The markup-only view of a single-file component: `<script>` and `<style>`
 * blocks and HTML comments removed. Script first, so a `<style>` string inside
 * script cannot confuse the style pass (and vice versa is impossible in valid
 * SFC markup).
 */
export function stripNonTemplateBlocks(text: string, options: StripNonTemplateOptions = {}): string {
  const preserveLines = options.preserveLines ?? false
  const withoutScripts = stripRegions(text, SCRIPT_BLOCK, preserveLines)
  const withoutStyles = stripRegions(withoutScripts, STYLE_BLOCK, preserveLines)
  return stripHtmlComments(withoutStyles, preserveLines)
}

/** Return every `<name ...>` opening tag, quote-aware so `>` in a value is safe. */
function openingTags(text: string, names: readonly string[]): string[] {
  const tags: string[] = []
  const pattern = new RegExp(`<(?:${names.join('|')})(?=[\\s/>])`, 'gi')
  for (const match of text.matchAll(pattern)) {
    let index = (match.index ?? 0) + match[0].length
    let quote: string | null = null
    while (index < text.length) {
      const char = text[index]
      if (quote !== null) {
        if (char === quote) quote = null
      } else if (char === '"' || char === "'") {
        quote = char
      } else if (char === '>') {
        break
      }
      index += 1
    }
    tags.push(text.slice(match.index, index + 1))
  }
  return tags
}

/** Split every static/dynamic `class` value on the tag into bare tokens. */
function classTokens(tag: string): Set<string> {
  const tokens = new Set<string>()
  for (const match of tag.matchAll(CLASS_ATTR)) {
    const raw = match[1] !== undefined ? match[1] : match[2]
    for (const token of raw.replace(CLASS_TOKEN_NOISE, ' ').split(CLASS_TOKEN_SEPARATORS)) {
      if (token) tokens.add(token)
    }
  }
  return tokens
}

function isCardContainer(tag: string): boolean {
  const tokens = classTokens(tag)
  if (tokens.has('card')) return true
  const rounded = [...tokens].some((token) => token === 'rounded' || token.startsWith('rounded-'))
  const bordered = [...tokens].some((token) => token === 'border' || token.startsWith('border-'))
  const padded = [...tokens].some((token) => PADDING_TOKEN.test(token))
  return rounded && bordered && padded
}

function isCardHeader(tag: string): boolean {
  const tokens = classTokens(tag)
  return tokens.has('font-semibold') && (tokens.has('text-base') || tokens.has('text-lg'))
}

/** Count raw `<button>` opening tags in template markup. */
export function countRawButtons(template: string): number {
  return (template.match(RAW_BUTTON_TAG) ?? []).length
}

/** Count raw `<input>` opening tags in template markup. */
export function countRawInputs(template: string): number {
  return (template.match(RAW_INPUT_TAG) ?? []).length
}

/** Count `import ... from 'primevue/badge'` statements in a component's script. */
export function countPrimeVueBadgeImports(source: string): number {
  return (source.match(PRIMEVUE_BADGE_IMPORT) ?? []).length
}

/** Offending DataCard/SectionCard tags that combine a title with padding="none". */
export function titledCardsWithoutPadding(text: string): string[] {
  const offenders: string[] = []
  for (const tag of openingTags(stripHtmlComments(text), ['DataCard', 'SectionCard'])) {
    if (!TITLE_ATTR.test(tag)) continue
    if (!PADDING_NONE.test(tag)) continue
    offenders.push(tag.split(/\s+/).join(' '))
  }
  return offenders
}

/** Count every ratchet fingerprint in one `.vue` file's source text. */
export function countPatterns(source: string): Record<Pattern, number> {
  const commented = stripHtmlComments(source)
  const template = stripNonTemplateBlocks(source)
  const script = stripJsBlockComments(commented)
  return {
    card_container: openingTags(template, ['div']).filter(isCardContainer).length,
    card_header: openingTags(template, ['h2', 'h3']).filter(isCardHeader).length,
    raw_dialog: (script.match(RAW_DIALOG_IMPORT) ?? []).length,
    raw_button: countRawButtons(template),
    raw_input: countRawInputs(template),
    primevue_badge: countPrimeVueBadgeImports(script),
  }
}

/** An all-zero `Counts`, derived from `PATTERNS` so a new pattern cannot be missed. */
export function emptyCounts(): Counts {
  return Object.fromEntries(PATTERNS.map((pattern) => [pattern, {}])) as Counts
}
